import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int jvmRelease = sc.nextInt();
        int n = sc.nextInt();
        int supported = jvmRelease + 44;
        int runnable = 0;
        for (int i = 0; i < n; i++) {
            String name = sc.next();
            int majorVersion = sc.nextInt();
            if (majorVersion <= supported) {
                runnable++;
                System.out.println(name + " RUN");
            } else {
                System.out.println(name + " UnsupportedClassVersionError " + (majorVersion - 44));
            }
        }
        System.out.println("runnable=" + runnable + "/" + n);
    }
}

