import java.util.*;

public class Main {
    static String classify(String term) {
        if (term.startsWith("JSR")) return "specification-request";
        if (term.startsWith("JEP")) return "proposal";
        if (Set.of("javac", "java", "jar", "javadoc", "jlink", "jshell").contains(term)) return "jdk-tool";
        if (Set.of("SpringBoot", "Quarkus").contains(term)) return "framework";
        if (term.equals("OpenLiberty")) return "runtime";
        return "unknown";
    }

    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int n = s.nextInt();
        List<String> kinds = List.of("specification-request", "proposal", "jdk-tool", "framework", "runtime", "unknown");
        Map<String, Integer> count = new LinkedHashMap<>();
        for (String k : kinds) count.put(k, 0);
        for (int i = 0; i < n; i++) {
            String term = s.next(), kind = classify(term);
            System.out.println(term + "=" + kind);
            count.merge(kind, 1, Integer::sum);
        }
        for (String k : kinds) System.out.println(k + "=" + count.get(k));
    }
}

