import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        int thisYear = s.nextInt(), minVersion = s.nextInt(), n = s.nextInt();
        Map<Integer, Integer> byVersion = new TreeMap<>();
        boolean action = false;
        for (int i = 0; i < n; i++) {
            String vendor = s.next();
            int version = s.nextInt(), endYear = s.nextInt();
            String status = version < minVersion ? "OUTDATED" : endYear < thisYear ? "UNSUPPORTED" : endYear == thisYear ? "EXPIRING" : "OK";
            if (!status.equals("OK")) action = true;
            System.out.println(vendor + " " + status);
            byVersion.merge(version, 1, Integer::sum);
        }
        System.out.println(action ? "ACTION_REQUIRED" : "ALL_OK");
        for (Map.Entry<Integer, Integer> e : byVersion.entrySet()) System.out.println(e.getKey() + " " + e.getValue());
    }
}
